import math, sympy as sp
h = sp.symbols('h', positive=True)
assert sp.limit((sp.sqrt(4 + h) - 2 - h/4)/h, h, 0) == 0
for k in range(1, 8):
    hh = -10.0**-k
    q = (-(abs(hh)**(1/3)))/hh
    assert abs(q/abs(hh)**(-2/3) - 1) < 1e-9
for k in range(1, 60):
    assert abs(math.sin(math.pi/2 + 2*k*math.pi) - 1) < 1e-9 and abs(math.sin(3*math.pi/2 + 2*k*math.pi) + 1) < 1e-9
a = sp.symbols('a')
def count(p, q):
    return len([s for s in sp.solve(a**2 - 2*p*a + q, a) if s.is_real])
assert count(0, -1) == 2 and count(1, 1) == 1 and count(0, 1) == 0 and count(1, -3) == 2

